const { t } = useI18n()
const toast = inject<{ error: (m: string) => void; success: (m: string) => void }>('toast')!

const props = defineProps<{ initialSection?: string }>()

// harness（DeepSeek Harness）是特殊的「集成」分类，不属于 RuntimeAdapter 多版本模型，
// 直接在环境管理内复用 SettingsDSH 组件承载安装/配置/服务/插件/更新。
const HARNESS_KEY = 'harness'
const HTTP_KEY = 'httpserve'
const PORTS_KEY = 'ports'
const SITES_KEY = 'sites'
const isHarness = computed(() => selectedId.value === HARNESS_KEY)
const isHttp = computed(() => selectedId.value === HTTP_KEY)
const isPorts = computed(() => selectedId.value === PORTS_KEY)
const isSites = computed(() => selectedId.value === SITES_KEY)

// 侧边栏分组（按职责划分）：语言运行时 / 网络服务 / 数据库 / 中间件 / AI 服务 / 开发工具 / 内置工具。
// 网络服务含 FTP（文件传输），故不复用旧名 webserver；中间件同时容纳 Redis/Memcached（缓存）
// 与 RabbitMQ/MinIO，旧名「缓存与存储」对它们名不副实；AI 服务收拢 Ollama 与 MCP 服务。
// 内置工具组承载 harness / HTTP 服务 / 端口三个「非可安装运行时」的页面入口。
const GROUP_ORDER = ['language', 'network', 'database', 'middleware', 'ai', 'tool', 'special']
const GROUP_LABEL: Record<string, string> = {
  language: 'groupLanguage',
  network: 'groupNetwork',
  database: 'groupDatabase',
  middleware: 'groupMiddleware',
  ai: 'groupAI',
  tool: 'groupTool',
  special: 'groupSpecial',
}

// 分组展开/收起状态（持久化到 localStorage）
const COLLAPSE_KEY = 'quickdock.env.collapsedGroups'
const collapsedGroups = reactive<Record<string, boolean>>(loadCollapsedGroups())
function loadCollapsedGroups(): Record<string, boolean> {
  try {
    const raw = localStorage.getItem(COLLAPSE_KEY)
    if (raw) return JSON.parse(raw) as Record<string, boolean>
  } catch (e) {
    console.warn('[env] 读取/保存分组折叠状态失败', e)
  }
  return {}
}
function toggleGroup(key: string) {
  collapsedGroups[key] = !collapsedGroups[key]
  try {
    localStorage.setItem(COLLAPSE_KEY, JSON.stringify(collapsedGroups))
  } catch (e) {
    console.warn('[env] 读取/保存分组折叠状态失败', e)
  }
}

interface SidebarItem {
  kind: 'runtime' | 'special'
  id: string
  name: string
  avatar: string
  color: string
  count?: number
  running?: boolean
  active: boolean
}
const sidebarGroups = computed(() => {
  const out: { key: string; labelKey: string; items: SidebarItem[]; collapsed: boolean; running: boolean }[] = []
  for (const g of GROUP_ORDER) {
    if (collapsedGroups[g]) {
      // 折叠态：仅保留分组标题，列表项清空（运行标识仍按全量运行时计算，折叠也能看到）
      out.push({ key: g, labelKey: GROUP_LABEL[g], items: [], collapsed: true, running: groupRunning(g) })
      continue
    }
    const items: SidebarItem[] = runtimes.value
      .filter((r) => r.group === g)
      .map((r): SidebarItem => ({
        kind: 'runtime',
        id: r.id,
        name: r.name,
        avatar: avatarIcon(r.id),
        color: avatarColor(r.id),
        count: r.installed.length,
        running: r.hasService && (runningCache[r.id] ?? false),
        active: selectedId.value === r.id,
      }))
      // 各分类下按名称首字母排序，保证展示稳定有序
      .sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base' }))
    // DSH（DeepSeek Harness）是 AI Agent 入口，归入 AI 服务组；它和 HTTP 服务/端口一样是页面入口而非可安装运行时，
    // 故以 kind: 'special' 注入，不参与上面的 runtime 列表与排序。
    if (g === 'ai') {
      items.push({ kind: 'special', id: HARNESS_KEY, name: t('navDsh'), avatar: 'DS', color: 'var(--color-accent)', active: isHarness.value, running: dshRunning.value })
    }
    if (g === 'special') {
      items.push({ kind: 'special', id: HTTP_KEY, name: t('httpServe'), avatar: '⬡', color: '#4a9eff', active: isHttp.value, running: httpAnyRunning.value })
      items.push({ kind: 'special', id: SITES_KEY, name: t('sitesTitle'), avatar: '⌂', color: '#e8a33d', active: isSites.value })
      items.push({ kind: 'special', id: PORTS_KEY, name: t('portsTitle'), avatar: '⇄', color: '#3ecf8e', active: isPorts.value })
    }
    if (items.length) out.push({ key: g, labelKey: GROUP_LABEL[g], items, collapsed: false, running: groupRunning(g) })
  }
  return out
})

// 分组级运行标识：该分组内任意「有服务」的运行时正在运行即点亮；
// AI 组额外纳入 DSH，内置工具组额外纳入 HTTP 服务的运行态。
// 站点不在其中：它自己不提供服务，而是由 nginx/caddy 提供服务 ——
// 那两者本就是运行时，跑起来时各自分组的绿点已经亮了。
// 即便分组被折叠，也依据全量运行时实时计算，不依赖已折叠隐藏的子项。
function groupRunning(key: string): boolean {
  for (const r of runtimes.value) {
    if (r.group === key && r.hasService && (runningCache[r.id] ?? false)) return true
  }
  if (key === 'ai' && dshRunning.value) return true
  if (key === 'special') {
    for (const v of Object.values(httpRunning)) if (v) return true
  }
  return false
}

interface SourceInfo {
  id: string
  name: string
}
interface Install {
  version: string
  scope: string // portable | system
  path: string
  active: boolean // 是否为环境变量指向的激活版本
  inSystemPath: boolean // 该版本 bin 目录是否真正在系统 PATH 中（后端读取 PATH 比对得出）
  alias: string // 用户别名
  note: string // 用户备注
}
interface ServiceStatus {
  running: boolean
  pid: number
  port: number
  // ports 后端按运行时配置文件解析出的全部侦听端口（caddy 首项为 admin 2019，其后为站点端口）
  ports?: number[]
  version: string
  // cpuPercent 近 3 秒（轮询间隔）内的 CPU 占用率，100% = 占满一个逻辑核。
  // 首次采样没有基线时为 null，前端显示「采样中」而不是编一个 0。
  cpuPercent?: number | null
  // memBytes 服务进程树常驻内存合计（含 nginx worker / Ollama runner 等子进程）
  memBytes?: number
  // procCount 进程树内的进程数
  procCount?: number
}
interface RuntimeInfo {
  id: string
  name: string
  group: string
  platforms: string[]
  recommended: string[]
  installed: Install[]
  sources: SourceInfo[]
  activeSource: string
  hasService: boolean
  hasLog: boolean
  webConsolePort: number
  enabled: boolean // 常驻开关：期望态（true=随应用自启/崩溃自愈，false=停止）
}

