function avatarIcon(id: string): string {
  return RUNTIME_ICONS[id] || `<span style="font-size:13px">${(id[0] || '?').toUpperCase()}</span>`
}

// 运行时目录是写死的（与后端 services/env/source.go registry 一一对应）：
// 侧栏挂载即静态渲染，EnvList 只负责填充已装版本/下载源/推荐版本等动态数据，
// 页面切换重挂载时列表恒在，杜绝「空列表 → 加载后填充」的闪烁。后端新增运行时需同步此表。
const STATIC_CATALOG: { id: string; name: string; group: string; hasService: boolean }[] = [
  { id: 'node', name: 'Node.js', group: 'language', hasService: false },
  { id: 'php', name: 'PHP', group: 'language', hasService: false },
  { id: 'go', name: 'Go', group: 'language', hasService: false },
  { id: 'bun', name: 'Bun', group: 'language', hasService: false },
  { id: 'erlang', name: 'Erlang', group: 'language', hasService: false },
  { id: 'nginx', name: 'Nginx', group: 'network', hasService: true },
  { id: 'caddy', name: 'Caddy', group: 'network', hasService: true },
  { id: 'traefik', name: 'Traefik', group: 'network', hasService: true },
  { id: 'redis', name: 'Redis', group: 'middleware', hasService: true },
  { id: 'memcached', name: 'Memcached', group: 'middleware', hasService: true },
  { id: 'mariadb', name: 'MariaDB', group: 'database', hasService: true },
  { id: 'mysql', name: 'MySQL', group: 'database', hasService: true },
  { id: 'postgresql', name: 'PostgreSQL', group: 'database', hasService: true },
  { id: 'mongodb', name: 'MongoDB', group: 'database', hasService: true },
  { id: 'minio', name: 'MinIO', group: 'middleware', hasService: true },
  { id: 'rabbitmq', name: 'RabbitMQ', group: 'middleware', hasService: true },
  { id: 'git', name: 'Git', group: 'tool', hasService: false },
  { id: 'composer', name: 'Composer', group: 'tool', hasService: false },
  { id: 'ffmpeg', name: 'FFmpeg', group: 'tool', hasService: false },
  { id: 'mailpit', name: 'Mailpit', group: 'tool', hasService: true },
  { id: 'frpc', name: 'frpc', group: 'tool', hasService: false },
  { id: 'gh', name: 'GitHub CLI', group: 'tool', hasService: false },
  { id: 'mkcert', name: 'mkcert', group: 'tool', hasService: false },
  { id: 'ollama', name: 'Ollama', group: 'ai', hasService: true },
  { id: 'python', name: 'Python', group: 'language', hasService: false },
  { id: 'jdk', name: 'JDK', group: 'language', hasService: false },
  { id: 'apache', name: 'Apache', group: 'network', hasService: true },
  { id: 'ftp', name: 'FTP', group: 'network', hasService: true },
  { id: 'webdav', name: 'WebDAV', group: 'network', hasService: true },
  { id: 'mcp', name: 'MCP 服务', group: 'ai', hasService: true },
]
function staticRuntime(s: typeof STATIC_CATALOG[number]): RuntimeInfo {
  return {
    id: s.id, name: s.name, group: s.group,
    platforms: [], recommended: [],
    installed: [], sources: [], activeSource: '',
    hasService: s.hasService, hasLog: false, webConsolePort: 0, enabled: false,
  }
}
const runtimes = ref<RuntimeInfo[]>(STATIC_CATALOG.map(staticRuntime))
const selectedId = ref<string>(props.initialSection || STATIC_CATALOG[0].id)
// 首次 EnvList 返回前不渲染「未安装版本」空状态：页面重挂载时数据从后端检测结果缓存
// 毫秒级回填，但仍有一个异步帧的空窗，避免空状态闪现后又被版本表替换。
const loadedOnce = ref(false)

const selected = computed<RuntimeInfo | null>(() => {
  return runtimes.value.find((r) => r.id === selectedId.value) || runtimes.value[0] || null
})

// 每个运行时的交互态，按 id 索引
interface UiState {
  version: string
  source: string
  custom: string
  installing: boolean
  stage: string
  message: string
  error: boolean          // message 是否为错误（红色样式 + 可复制）
  written: number
  total: number
  speed: number            // 下载速度（字节/秒），用于显示
  eta: number              // 预计剩余秒数，用于显示
  available: string[]      // 已获取的可选版本列表（加载后）
  fetching: boolean        // 正在拉取版本列表
  loadError: string        // 拉取失败时的错误信息（空=无错误）
  listExpanded: boolean    // 版本列表是否展开（点击 ▾ 切换）
  svc: Record<string, ServiceStatus>
}
const ui = reactive<Record<string, UiState>>({})

// 端口冲突探测结果（按运行时 id 索引）：后端 EnvPortConflict 返回默认服务端口是否被其它程序占用。
interface PortConflict {
  occupied: boolean
  port: number
  pid: number
  image: string
  ours: boolean // 占用者是否就是本会话拉起的该运行时
}
const portConflicts = reactive<Record<string, PortConflict>>({})

// PATH 可视化面板：聚合所有已激活运行时的 bin 目录及其在系统 PATH 中的状态
const pathModal = reactive<{ open: boolean }>({ open: false })
function binDirOf(ins: any): string {
  if (ins.scope === 'system') {
    const parts = (ins.path || '').split(/[\\/]/)
    parts.pop()
    return parts.join('/')
  }
  return ins.path || ''
}
const pathEntries = computed(() => {
  const out: { id: string; name: string; version: string; binDir: string; inPath: boolean }[] = []
  for (const r of runtimes.value) {
    if (!r.installed) continue
    for (const ins of r.installed) {
      if (ins.active) {
        out.push({ id: r.id, name: r.name, version: ins.version, binDir: binDirOf(ins), inPath: !!ins.inSystemPath })
      }
    }
  }
  return out
})

// 端口全景：聚合所有运行中服务的运行时 / 版本 / 服务端口 / 控制台端口。
const panorama = reactive<{ open: boolean }>({ open: false })
// 打开端口全景前，预取各 RabbitMQ 版本的管理后台状态，使「控制台」列准确（其余运行时端口为静态常量，无需探测）。
function openPanorama() {
  panorama.open = true
  for (const r of runtimes.value) {
    if (r.id !== 'rabbitmq') continue
    for (const ins of (r.installed || [])) {
      if (rabbitMgmt[ins.version] === undefined) fetchMgmt(ins.version)
    }
  }
}
const panoramaEntries = computed(() => {
  const out: { id: string; name: string; version: string; port: number; ports: number[]; consolePort: number }[] = []
  for (const r of runtimes.value) {
    if (!r.hasService) continue
    for (const ins of (r.installed || [])) {
      if (!svcOn(r, ins.version)) continue
      out.push({ id: r.id, name: r.name, version: ins.version, port: svcPort(r, ins.version), ports: svcPorts(r, ins.version), consolePort: consolePort(r, ins) })
    }
  }
  // 内置 HTTP 静态服务（目录 → 静态站点）同样占用端口，必须计入全景：
  // 此前只遍历 runtimes，导致开启 HTTP 服务后「端口全景」里根本看不到它。
  // 控制台列直接给服务端口：openConsole 打开 127.0.0.1:<port>，正好就是该站点。
  for (const s of httpServers.value) {
    if (!httpRunning[s.id]) continue
    out.push({ id: HTTP_KEY, name: t('httpServe'), version: s.name, port: s.port, ports: [s.port], consolePort: s.port })
  }
  // dsh（harness）web 服务同样占用端口，必须计入全景：
  // 此前只遍历 runtimes + HTTP 服务，导致 dsh 跑着在「端口全景」里也看不到。
  // 用 DSHStatus 返回的真实端口（可能是兜底随机端口，而非写死的 3080），避免错标。
  if (dshRunning.value && dshPort.value) {
    out.push({ id: HARNESS_KEY, name: t('navDsh'), version: '', port: dshPort.value, ports: [dshPort.value], consolePort: dshPort.value })
  }
  return out
})

// 当前选中运行时的端口冲突（无探测结果时返回零值）
const selectedConflict = computed<PortConflict | null>(() => {
  return portConflicts[selectedId.value] || null
})

function stateFor(id: string, info: RuntimeInfo): UiState {
  if (!ui[id]) {
    ui[id] = {
      version: '',
      source: '',
      custom: '',
      installing: false,
      stage: '',
      message: '',
      error: false,
      written: 0,
      total: -1,
      speed: 0,
      eta: 0,
      available: [],
      fetching: false,
      loadError: '',
      listExpanded: false,
      svc: {},
    }
  }
  const s = ui[id]
  // 静态目录首建时 activeSource 还是空，EnvList 合并后回填一次。
  // 版本号不在此默认（避免一进面板就显示推荐版本）：上游拉取成功后由 loadAvailable 填最新版本，拉取失败则保持空。
  if (!s.source && (info.activeSource || info.sources[0]?.id)) {
    s.source = info.activeSource || info.sources[0]?.id || ''
  }
  return s
}

// failState 把运行时的错误持久化到可复制的 .env-msg 区域（toast 仅作瞬时提示），避免报错一闪而过且无法复制。
function failState(r: RuntimeInfo, e: any) {
  const s = stateFor(r.id, r)
  s.message = getErrorMessage(e)
  s.error = true
  s.installing = false
  toast.error(s.message)
}


