  }
}

// 设置/取消环境变量：未设置的版本注册其 bin 目录到系统 PATH；已设置的注销其 bin 目录。
// 取消走 EnvUnsetActive（直接按版本注销，不依赖 active 元数据），避免元数据漂移导致 PATH 残留旧版本。
async function toggleEnvVar(r: RuntimeInfo, ins: Install) {
  try {
    if (ins.inSystemPath) {
      unwrap(await EnvUnsetActive(r.id, ins.version))
    } else {
      unwrap(await EnvSetActive(r.id, ins.version))
    }
    await load()
  } catch (e: any) {
    failState(r, e)
  }
}

// 操作列下拉菜单（设置别名 / 删除 收纳于此）
const openMenu = ref<string | null>(null)
function toggleMenu(v: string) {
  const willOpen = openMenu.value !== v
  openMenu.value = willOpen ? v : null
  // 展开 RabbitMQ 操作菜单时，拉取管理后台启用状态以决定显示「启用/关闭」
  if (willOpen && selected.value?.id === 'rabbitmq') {
    const ins = selected.value.installed.find(i => i.version === v)
    if (ins) fetchMgmt(ins.version)
  }
}

// 删除确认弹窗（替换原生 confirm，统一风格）
const confirmDelete = reactive<{ open: boolean; runtime: string; version: string; scope: string; removeData: boolean }>({
  open: false,
  runtime: '',
  version: '',
  scope: '',
  removeData: false,
})
// 卸载时可选择性清理数据目录的运行时（这些 runtime 实现了 DataDirProvider）
const HAS_DATA_DIR = new Set(['postgresql', 'mariadb', 'mysql', 'mongodb', 'minio', 'mailpit'])
function askDelete(r: RuntimeInfo, ins: Install) {
  if (ins.scope === 'system') {
    toast.error(t('systemCannotDelete'))
    return
  }
  confirmDelete.runtime = r.id
  confirmDelete.version = ins.version
  confirmDelete.scope = ins.scope
  confirmDelete.removeData = false
  confirmDelete.open = true
  openMenu.value = null
}
async function doDelete() {
  try {
    unwrap(await EnvDeleteVersion(confirmDelete.runtime, confirmDelete.version, confirmDelete.removeData))
    toast.success(t('deleted'))
