// ---- 新版本检测：上游可下载版本 vs 已安装版本 ----
// 版本号形如 "v22.22.2" / "1.25.0" / "8.3.20"，去掉前缀 v 后按数值逐段比较
function cmpVer(a: string, b: string): number {
  const pa = String(a || '').trim().replace(/^v/i, '').split('.').map((n) => parseInt(n, 10) || 0)
  const pb = String(b || '').trim().replace(/^v/i, '').split('.').map((n) => parseInt(n, 10) || 0)
  for (let i = 0; i < 3; i++) {
    const x = pa[i] || 0
    const y = pb[i] || 0
    if (x !== y) return x < y ? -1 : 1
  }
  return 0
}
// newestUpdate: 上游最新版本高于已装版本时给出升级提示
// available 为空时用 recommended[0] 兜底（推荐版本通常为最新 LTS）
const newestUpdate = computed(() => {
  const r = selected.value
  const s = r ? ui[r.id] : null
  if (!r) return null
  const candidates = s?.available?.length ? s.available : r.recommended
  if (!candidates?.length) return null
  const to = candidates[0] // 已降序，第一条即最新
  const from = r.installed.reduce((m, i) => (cmpVer(i.version, m) > 0 ? i.version : m), '')
  if (!from || cmpVer(to, from) <= 0) return null
  return { from, to }
})
function applyUpdate(to: string) {
  const r = selected.value
  if (!r) return
  stateFor(r.id, r).version = to
  install(r)
}

let polling = false
async function pollStatus() {
  if (polling) return // 上一次轮询（含多次 EnvStatus 调用）尚未返回时跳过，避免请求叠加导致状态闪烁
  polling = true
  try {
    for (const r of runtimes.value) {
      if (!r.hasService) { commitRuntimeCache(r); continue }
      const s = ui[r.id]
      if (!s) { commitRuntimeCache(r); continue }
      for (const ins of r.installed) {
        // linked（导入）版本一般不参与服务管理；PHP 例外——导入版 PHP 也能以 php-fpm 方式启停
        if (ins.scope === 'linked' && r.id !== 'php') continue
        try {
          const st = unwrap<ServiceStatus>(await EnvStatus(r.id, ins.version))
          if (st) s.svc[ins.version] = st
        } catch {
          /* 忽略单次轮询失败 */
        }
      }
      // 端口冲突探测（启动前可视化提示）：仅对已装服务的运行时查询一次
      if (r.installed.length) {
        try {
          const pc = unwrap<PortConflict>(await EnvPortConflict(r.id, r.installed[0].version))
          if (pc) portConflicts[r.id] = pc
        } catch {
          /* 忽略单次探测失败 */
        }
      }
      commitRuntimeCache(r)
    }
    await loadDshRunning()
    // HTTP 服务的绿点此前只在点进对应标签页或首次挂载时刷新，
    // 在面板里启动/停止后再回侧栏，绿点仍是陈旧状态。这里并入 3s 轮询，
    // 与 dsh 同范式，保证侧栏入口的运行态始终反映真实情况。
    await loadHTTPServers()
  } finally {
    polling = false
  }
}

// 下载速度/ETA 估算状态（相邻两次进度事件的时间差）
let lastProg = { t: 0, written: 0 }
function onProgress(payload: any) {
  const p = payload?.data ?? payload
  const rt = p?.runtime
  if (!rt || !ui[rt]) return
  const s = ui[rt]
  s.stage = p.stage || ''
  if (p.message) s.message = p.message
  if (typeof p.written === 'number') s.written = p.written
  if (typeof p.total === 'number') s.total = p.total
  // 下载/解压阶段估算速度与时长（基于相邻两次进度事件的时间差）
  if ((p.stage === 'download' || p.stage === 'extract') && typeof p.written === 'number' && p.total > 0) {
    const now = Date.now()
    if (lastProg.t > 0 && p.written > lastProg.written) {
      const dt = (now - lastProg.t) / 1000
      const dw = p.written - lastProg.written
      if (dt > 0.05 && dw > 0) {
        const speed = dw / dt
        s.speed = speed
        s.eta = (p.total - p.written) / speed
      }
    }
    lastProg = { t: now, written: p.written }
  } else {
    lastProg = { t: 0, written: 0 }
    s.speed = 0
    s.eta = 0
  }
  if (p.stage === 'done') {
    s.installing = false
    s.written = 0
    s.total = -1
    s.speed = 0
    s.eta = 0
    s.message = ''
    s.error = false
    toast.success(rt.toUpperCase() + ' ' + t('envInstalled'))
    load()
  } else if (p.stage === 'error') {
    s.installing = false
    s.written = 0
    s.total = -1
    s.speed = 0
    s.eta = 0
    s.message = p.message || t('envInstallFailed')
    s.error = true
    toast.error(rt.toUpperCase() + ': ' + s.message)
  } else if (p.stage === 'download' || p.stage === 'extract') {
    s.installing = true
  }
}

async function install(r: RuntimeInfo) {
  const s = stateFor(r.id, r)
  if (s.installing) return
  s.installing = true
    s.stage = 'download'
    s.written = 0
    s.total = -1
    s.message = ''
    s.error = false
  try {
    const custom = s.source === 'custom' ? s.custom : ''
    unwrap(await EnvInstall(r.id, s.version, s.source, custom))
  } catch (e: any) {
    failState(r, e)
  }
}

// updateOllama 更新到检测到的最新版。
// 走既有 install 流程（EnvInstall → OllamaRuntime.Install 原地替换，配置保留），
// 只是先把目标版本写进 ui state——版本下拉在单版本语义下不展示，用户只能从这里触发。
function updateOllama() {
  const r = selected.value
  const latest = ollamaUpdate.value?.latest
  if (!r || r.id !== 'ollama' || !latest) return
  const s = stateFor('ollama', r)
  s.version = latest
  install(r)
}

// Git 未检测到本地安装时的一键安装：用推荐版本（第一个）直接装，避开手输版本号。
function installGitLatest() {
  const r = selected.value
  if (!r || r.id !== 'git') return
  const s = stateFor(r.id, r)
  // 优先用上游推荐列表（拉取后）；未拉到则用 EnvList 返回的 recommended 兜底
  const latest = s.available?.[0] || r.recommended?.[0] || ''
  if (!latest) {
    toast.error(t('envLoadFailed'))
    return
  }
  s.version = latest
  install(r)
}

// ---- Git 状态表（版本/路径/SSH/Git LFS）----
const gitInfo = ref<GitStatusInfo | null>(cachedGitInfo)

async function loadGitInfo() {
  if (selected.value?.id !== 'git') {
    // 切走 git 时不清空，保留缓存供下次切回立即预填（消除闪现）
    return
  }
  // 先预填上次缓存，再后台刷新最新数据；首次无缓存（null）时显示空表属正常
  gitInfo.value = cachedGitInfo
  try {
    const res = unwrap<GitStatusInfo>(await EnvGitStatus())
    cachedGitInfo = res
    gitInfo.value = res
  } catch (e: any) {
    // 刷新失败保留已预填的缓存，不清空
  }
}

function sshStatusClass(s: GitStatusInfo['ssh']): string {
  if (s.result === 'ok') return 'ok'
  if (s.result === 'no-key' || s.result === 'n/a') return 'warn'
  return 'fail'
}
function sshResultText(s: GitStatusInfo['ssh']): string {
  if (s.result === 'ok') return t('gitSshOk')
  if (s.result === 'no-key') return t('gitSshNoKey')
  if (s.result === 'n/a') return t('gitSshNA')
  return s.output || t('gitSshFail')
}

// 状态表行：每行一个 Git 维度，列固定为 Item / Status / Command / Path / Result
const gitRows = computed(() => {
  const g = gitInfo.value
  if (!g) return []
  return [
    { item: t('gitVersion'), status: g.installed ? 'ok' : 'missing', command: 'git --version', path: '', result: g.version || t('notInstalled') },
    { item: t('gitPath'), status: g.installed ? 'ok' : 'missing', command: 'where git', path: g.path, result: g.path || t('notInstalled') },
    { item: 'SSH', status: sshStatusClass(g.ssh), command: g.ssh.command, path: g.ssh.keyPath, result: sshResultText(g.ssh) },
    { item: 'Git LFS', status: g.lfs.installed ? 'ok' : 'missing', command: g.lfs.command, path: '', result: g.lfs.version || t('notInstalled') },
  ]
})

// 常驻开关：把运行时设为「期望态」。开=随应用自启/崩溃自愈，关=停止。
// 不再暴露手动 start/stop 单次动作，由后端监督器对账拉起。
const settingEnabled = reactive<Record<string, boolean>>({})
async function toggleEnabled(r: RuntimeInfo, on: boolean) {
  settingEnabled[r.id] = true
  // 乐观更新，保证开关手感即时
  const target = runtimes.value.find((x) => x.id === r.id)
  if (target) target.enabled = on
  try {
    unwrap(await EnvSetEnabled(r.id, on))
    toast.success(r.name + ' ' + (on ? t('svcWatchOn') : t('svcWatchOff')))
    await pollStatus()
    refreshRuntimeCacheNow(r)
    refreshOllamaPanel(on ? 1200 : 0)
  } catch (e: any) {
    // 失败回滚乐观状态
    if (target) target.enabled = !on
    toast.error(getErrorMessage(e))
  } finally {
    settingEnabled[r.id] = false
  }
}

// stopping[rt+version] 标记某版本正在停止，期间禁用按钮避免重复点击
const stopping = reactive<Record<string, boolean>>({})
// stopService 停止服务。若该运行时处于「常驻」期望态，一并撤销该期望态——
// 否则看门狗会在下一个巡检周期把它拉回来，用户会以为「停止无效」。
// 场景应用拉起的服务本就非常驻（enabled=false），直接停即可。
async function stopService(r: RuntimeInfo, ins: Install) {
  const key = r.id + ins.version
  stopping[key] = true
  try {
    if (r.enabled) {
      unwrap(await EnvSetEnabled(r.id, false))
      const target = runtimes.value.find((x) => x.id === r.id)
      if (target) target.enabled = false
    } else {
      unwrap(await EnvStop(r.id))
    }
    toast.success(r.name + ' ' + t('svcStopped'))
    await pollStatus()
    refreshRuntimeCacheNow(r)
    refreshOllamaPanel()
  } catch (e: any) {
    toast.error(getErrorMessage(e))
  } finally {
    stopping[key] = false
  }
}

// restarting[rt+version] 标记某版本正在重启，期间禁用按钮避免重复点击
const restarting = reactive<Record<string, boolean>>({})
async function restartService(r: RuntimeInfo, ins: Install) {
  const key = r.id + ins.version
  restarting[key] = true
  try {
    unwrap(await EnvRestart(r.id, ins.version))
    toast.success(r.name + ' ' + ins.version + ' ' + t('svcRestartDone'))
    await pollStatus()
    refreshRuntimeCacheNow(r)
    refreshOllamaPanel(1200)
  } catch (e: any) {
    toast.error(getErrorMessage(e))
  } finally {
    restarting[key] = false
  }
}

// consolePort 返回某运行时某版本的 Web 管理后台端口（0=无）。
// RabbitMQ 仅在管理后台插件启用时才有控制台；其余运行时（MinIO 9001 / Mailpit 8025 / Traefik 8080）端口固定。
function consolePort(r: RuntimeInfo, ins: Install): number {
  if (r.id === 'rabbitmq') return rabbitMgmt[ins.version] ? 15672 : 0
  return r.webConsolePort || 0
}
function openConsole(port: number) {
  window.open('http://127.0.0.1:' + port + '/', '_blank')
}

// ---- 通用日志查看器（任意实现了 LogProvider 的运行时）----
// 与 Redis 弹窗共用 filteredLog 的滚动逻辑（logEl 引用），但独立维护一份状态，避免互相干扰。
const logModal = reactive<{
  open: boolean; runtime: string; version: string; log: string
  logFilter: string; logAuto: boolean
}>({
  open: false, runtime: '', version: '', log: '',
  logFilter: '', logAuto: false,
})
const filteredLogModal = computed(() => {
  const f = logModal.logFilter.trim().toLowerCase()
  if (!f) return logModal.log
  return logModal.log.split('\n').filter((l) => l.toLowerCase().includes(f)).join('\n')
})
let logModalTimer: ReturnType<typeof setInterval> | null = null
async function openLog(r: RuntimeInfo, ins: Install) {
  try {
    logModal.runtime = r.id
    logModal.version = ins.version
    logModal.log = unwrap<string>(await EnvLogGet(r.id, ins.version)) || ''
    logModal.logFilter = ''
    logModal.logAuto = false
    logModal.open = true
    openMenu.value = null
    nextTick(scrollLogBottom)
  } catch (e: any) {
    toast.error(getErrorMessage(e))
  }
}
async function refreshLogModal() {
  try {
    logModal.log = unwrap<string>(await EnvLogGet(logModal.runtime, logModal.version)) || ''
  } catch (e: any) {
    toast.error(getErrorMessage(e))
  }
}
function startLogModalAuto() {
  if (logModalTimer || !logModal.logAuto) return
  logModalTimer = setInterval(() => refreshLogModal(), 2000)
}
function stopLogModalAuto() {
  if (logModalTimer) { clearInterval(logModalTimer); logModalTimer = null }
}
function toggleLogModalAuto() {
  logModal.logAuto = !logModal.logAuto
  if (logModal.logAuto) { refreshLogModal(); startLogModalAuto() }
  else stopLogModalAuto()
}
function closeLogModal() {
  stopLogModalAuto()
  logModal.open = false
}

// 启用 RabbitMQ 管理后台插件（rabbitmq_management，端口 15672），针对运行中的节点在线启用。
const mgmtEnabling = ref(false)
// rabbitMgmt[version] = 管理后台是否已启用（决定是否显示「启用/关闭」以及端口是否显示两个）
const rabbitMgmt = reactive<Record<string, boolean>>({})
async function fetchMgmt(version: string) {
  try {
    rabbitMgmt[version] = !!unwrap<boolean>(await EnvRabbitMQIsMgmtEnabled(version))
  } catch {
    rabbitMgmt[version] = false
  }
}
async function enableRabbitMgmt(ins: Install) {
  if (mgmtEnabling.value) return
  mgmtEnabling.value = true
  try {
    const out = unwrap(await EnvRabbitMQEnableMgmt(ins.version))
    toast.success(t('rabbitmqEnableMgmtDone'))
    if (out) logDebug('[RabbitMQ mgmt]', out)
    rabbitMgmt[ins.version] = true
    pollStatus()
  } catch (e: any) {
    toast.error(t('rabbitmqEnableMgmtFail') + ': ' + getErrorMessage(e))
  } finally {
    mgmtEnabling.value = false
  }
}
async function disableRabbitMgmt(ins: Install) {
  if (mgmtEnabling.value) return
  mgmtEnabling.value = true
  try {
    const out = unwrap(await EnvRabbitMQDisableMgmt(ins.version))
    toast.success(t('rabbitmqDisableMgmtDone'))
    if (out) logDebug('[RabbitMQ mgmt]', out)
    rabbitMgmt[ins.version] = false
    pollStatus()
  } catch (e: any) {
    toast.error(t('rabbitmqDisableMgmtFail') + ': ' + getErrorMessage(e))
  } finally {
    mgmtEnabling.value = false
  }
}
// 根据当前启用状态切换：已启用→关闭；未启用→启用
async function toggleRabbitMgmt(ins: Install) {
  if (rabbitMgmt[ins.version]) await disableRabbitMgmt(ins)
  else await enableRabbitMgmt(ins)
}

let off: (() => void) | null = null
let offRefreshed: (() => void) | null = null
let offOllamaPull: (() => void) | null = null
let timer: number | null = null
// 点击外部时收起版本列表
function onDocClick(e: MouseEvent) {
  const target = e.target as HTMLElement
  if (!target.closest('.install-input-wrap')) {
    for (const id in ui) {
      if (ui[id].listExpanded) ui[id].listExpanded = false
    }
  }
}
onMounted(() => {
  // 首次轮询必须在运行列表就绪后执行：否则 pollStatus 会空跑（runtimes 为空），
  // 绿点缓存要等到 3s 定时器那轮才填充，导致刚进环境管理绿点不显示。
  load().finally(() => pollStatus())
  loadHTTPServers()
  loadDshRunning()
  loadConfigSupport(selectedId.value) // 初始选中运行时的配置编辑入口
  ensureCertLoaded()                   // 若初始选中即 mkcert，预载证书区块状态
  document.addEventListener('click', onDocClick)
  off = Events.On('quickdock:env:progress', onProgress)
  // 后台重扫完成（启动扫描 / 手动刷新按钮 / 安装完成后）→ 重新读取持久化缓存
  offRefreshed = Events.On('quickdock:env:refreshed', () => { load(); ensureCertLoaded(); pollStatus(); refreshOllamaPanel() })
  offOllamaPull = Events.On('quickdock:env:ollama:pull', onOllamaPull)
  timer = window.setInterval(pollStatus, 3000)
})
// 切换运行时时自动拉取对应可下载版本列表（harness / http / sites / ports 区块不触发）
watch(selectedId, (id) => {
  if (id && id !== HARNESS_KEY && id !== HTTP_KEY && id !== SITES_KEY && id !== PORTS_KEY) {
    loadAvailable(id)
    loadConfigSupport(id) // 通用「编辑配置」入口是否显示
  } else {
    configSupported.value = false
  }
  // 切到 mkcert 时拉取证书区块状态
  if (id === 'mkcert') ensureCertLoaded()
  // 切到 harness（dsh）时同步其运行态，保证侧栏绿点即时刷新
  if (id === HARNESS_KEY) loadDshRunning()
  // Git 区块切换时拉取状态表
  loadGitInfo()
})
// 侧边栏 harness 入口要求切换区块时同步定位
watch(() => props.initialSection, (v) => {
  if (v) selectedId.value = v
})
onUnmounted(() => {
  document.removeEventListener('click', onDocClick)
  if (off) off()
  if (offRefreshed) offRefreshed()
  if (offOllamaPull) offOllamaPull()
  if (timer) clearInterval(timer)
  if (logTimer) clearInterval(logTimer)
  if (logModalTimer) clearInterval(logModalTimer)
})

// s = currentRuntimeState，模板中复用，避免反复调用 stateFor
const s = currentRuntimeState
</script>

