                @blur="closeOllamaLibSoon"
                @keyup.enter="pullOllamaModel"
              />
              <!-- 官方模型库候选：输入即过滤，聚焦即展开（首次拉热门） -->
              <div v-if="ollamaLibOpen && (ollamaLibModels.length || ollamaLibLoading)" class="lib-dropdown">
                <div v-if="ollamaLibLoading && !ollamaLibModels.length" class="lib-loading">{{ t('ollamaLibLoading') }}</div>
                <div
                  v-for="m in ollamaLibModels"
                  :key="m.name"
                  class="lib-option"
                  @mousedown.prevent="pickOllamaLib(m.name)"
                >
                  <span class="lib-name">{{ m.name }}</span>
                  <span v-if="m.size" class="lib-size">{{ ollamaSize(m.size) }}</span>
                </div>
              </div>
            </div>
            <button class="op-btn" :disabled="ollamaPulling || !ollamaPullName.trim()" @click="pullOllamaModel">
              {{ ollamaPulling ? t('ollamaPulling') : t('ollamaPullBtn') }}
            </button>
          </div>

          <div v-if="ollamaProgress" class="ollama-prog">
            <div class="ollama-prog-bar">
              <div
                class="ollama-prog-fill"
                :class="{ unknown: !ollamaProgress.total }"
                :style="{ width: ollamaProgress.total ? ollamaProgress.percent + '%' : '40%' }"
              ></div>
            </div>
            <div class="ollama-prog-meta">
              <span class="ollama-prog-pct">{{ ollamaProgress.percent.toFixed(1) }}%</span>
              <span v-if="ollamaProgress.total">{{ ollamaSize(ollamaProgress.completed) }} / {{ ollamaSize(ollamaProgress.total) }}</span>
              <span class="ollama-prog-status">{{ ollamaProgress.status }}</span>
            </div>
          </div>

          <div v-if="ollamaErr" class="env-msg error">{{ ollamaErr }}</div>

          <div v-if="ollamaModels.length" class="ver-table">
            <div class="ver-row ver-head ollama-row">
              <span class="col-ver">{{ t('ollamaColModel') }}</span>
              <span class="col-env">{{ t('ollamaColSize') }}</span>
              <span class="col-path">{{ t('ollamaColDetail') }}</span>
              <span class="col-ops">{{ t('operations') }}</span>
            </div>
            <div v-for="m in ollamaModels" :key="m.name" class="ver-row ollama-row">
              <div class="col-ver"><span class="ver-ver">{{ m.name }}</span></div>
              <div class="col-env">{{ ollamaSize(m.size) }}</div>
              <div class="col-path">
                <span>{{ [m.details?.parameter_size, m.details?.quantization_level].filter(Boolean).join(' · ') || '—' }}</span>
                <span class="ollama-time">{{ ollamaTime(m.modified_at) }}</span>
              </div>
              <div class="col-ops">
                <button class="op-btn" @click="copyOllamaModel(m.name)">{{ t('copy') }}</button>
                <button class="op-btn danger" @click="ollamaDelTarget = m">{{ t('delete') }}</button>
              </div>
            </div>
          </div>
          <div v-else-if="!ollamaLoading && !ollamaErr" class="empty-hint">{{ t('ollamaNoModels') }}</div>

          <!-- 下载完只是第一步：说清模型怎么用，避免用户拉完不知道下一步 -->
          <div v-if="ollamaModels.length" class="ollama-usage">
            <div class="usage-title">{{ t('ollamaHowToUse') }}</div>
            <div class="usage-row">
              <span class="usage-k">{{ t('ollamaUsageEndpoint') }}</span>
              <code class="usage-v">{{ ollamaBaseURL }}</code>
              <button class="op-btn" @click="copyOllamaText(ollamaBaseURL)">{{ t('copy') }}</button>
            </div>
            <div class="usage-row">
              <span class="usage-k">{{ t('ollamaUsageModel') }}</span>
              <code class="usage-v">{{ ollamaModels[0].name }}</code>
              <button class="op-btn" @click="copyOllamaText(ollamaModels[0].name)">{{ t('copy') }}</button>
            </div>
            <div class="usage-tip">{{ t('ollamaUsageTip') }}</div>
          </div>

          <template v-if="ollamaRunning.length">
            <div class="block-head ollama-sub-head">
              <span class="block-title">{{ t('ollamaRunningTitle') }}</span>
              <span class="block-count">{{ ollamaRunning.length }}</span>
            </div>
            <div class="ver-table">
              <div class="ver-row ver-head ollama-run-row">
                <span class="col-ver">{{ t('ollamaColModel') }}</span>
                <span class="col-env">{{ t('ollamaColVram') }}</span>
                <span class="col-path">{{ t('ollamaColExpires') }}</span>
              </div>
              <div v-for="m in ollamaRunning" :key="m.name" class="ver-row ollama-run-row">
                <div class="col-ver"><span class="ver-ver">{{ m.name }}</span></div>
                <div class="col-env">{{ ollamaSize(m.size_vram) }}</div>
                <div class="col-path">{{ ollamaTime(m.expires_at) }}</div>
              </div>
            </div>
          </template>
        </section>

        <!-- 本地可信证书签发（mkcert 专属能力）：随 mkcert 分类内联展示 -->
        <section v-if="selected.id === 'mkcert'" class="detail-block cert-panel">
          <div class="block-head">
            <span class="block-title">{{ t('certTitle') }}</span>
            <span class="block-count cert-sub">{{ t('certSubtitle') }}</span>
          </div>

          <div v-if="!certModal.status?.exe" class="env-msg error cert-msg">{{ certModal.status?.message || t('certExeMissing') }}</div>
          <template v-else>
            <div class="cert-root-line">
              <span>{{ t('certRootStatus') }}</span>
              <span v-if="certModal.status?.rootTrusted" class="badge ok">{{ t('certRootTrusted') }}</span>
              <span v-else class="badge warn">{{ t('certRootUntrusted') }}</span>
              <button v-if="!certModal.status?.rootTrusted" class="op-btn small" :disabled="certModal.busy" @click="certInstallRoot()">
                {{ certModal.busy ? t('certTrusting') : t('certTrustBtn') }}
              </button>
            </div>

            <div class="cert-grid">
              <label class="cert-label">{{ t('certHosts') }}</label>
              <input v-model="certModal.hosts" class="env-input" :placeholder="t('certHostsPh')" />
              <label class="cert-label">{{ t('certName') }}</label>
              <input v-model="certModal.name" class="env-input" placeholder="localhost" />
              <label class="cert-label">{{ t('certOutDir') }}</label>
              <div class="cert-dir-row">
                <input v-model="certModal.outDir" class="env-input" placeholder="C:\path\to\certs" />
                <button class="op-btn" @click="certPickDir()">{{ t('certPick') }}</button>
              </div>
            </div>

            <p v-if="certModal.error" class="env-msg error cert-msg">{{ certModal.error }}</p>
            <div class="cert-actions">
              <button class="env-install-btn" :class="{ busy: certModal.busy }" :disabled="certModal.busy" @click="certIssue()">
                {{ certModal.busy ? t('certIssuing') : t('certIssueBtn') }}
              </button>
              <template v-if="certModal.result">
                <span class="cert-result-label">{{ t('certResult') }}</span>
                <textarea readonly class="env-textarea mono cert-result" rows="2" :value="certModal.result"></textarea>
              </template>
            </div>
            <p class="cert-hint">{{ t('certHint') }}</p>
          </template>
        </section>

        <!-- Git 状态表：版本 / 路径 / SSH / Git LFS -->
        <section v-if="selected.id === 'git'" class="detail-block">
          <div class="block-head">
            <span class="block-title">{{ t('gitStatus') }}</span>
            <span v-if="gitInfo" class="block-count">{{ gitInfo.version || '—' }}</span>
          </div>
          <div v-if="gitInfo" class="git-table">
            <div class="git-row git-head">
              <span class="g-item">{{ t('item') }}</span>
              <span class="g-status">{{ t('status') }}</span>
              <span class="g-cmd">{{ t('command') }}</span>
              <span class="g-path">{{ t('path') }}</span>
              <span class="g-result">{{ t('result') }}</span>
            </div>
            <div v-for="row in gitRows" :key="row.item" class="git-row">
              <span class="g-item">{{ row.item }}</span>
              <span class="g-status">
                <span class="status-dot" :class="row.status"></span>{{ row.status }}
              </span>
              <span class="g-cmd"><code>{{ row.command }}</code></span>
              <span class="g-path clickable" v-if="row.path" :title="t('openInExplorer') + ': ' + row.path" @click="reveal(row.path)">{{ row.path }}</span>
              <span class="g-path" v-else>—</span>
              <span class="g-result" :title="row.result">{{ row.result }}</span>
            </div>
          </div>
          <div v-else-if="loadedOnce && !selected.installed.length" class="empty-state">
            <div class="empty-icon">∅</div>
            <div class="empty-text">{{ t('noInstalledVersion') }}</div>
            <div class="empty-actions">
              <button class="env-install-btn" :disabled="stateFor(selected.id, selected).installing" @click="installGitLatest">{{ t('installGitLatest') }}</button>
            </div>
          </div>
        </section>

        <!-- 已下载 / 已安装版本（非 Git 运行时） -->
        <section v-else class="detail-block">
          <div class="block-head">
            <span class="block-title">{{ t('installedVersions') }}</span>
            <span class="block-count">{{ selected.installed.length }}</span>
            <!-- Ollama 是单版本语义（目录固定、无版本共存），导入外部安装无意义，故不提供 -->
            <button
              v-if="selected.id !== 'git' && selected.id !== 'mcp' && selected.id !== 'webdav' && selected.id !== 'ollama'"
              class="link-btn import-btn"
              @click="importExisting(selected)"
            >{{ t('importExisting') }}</button>
          </div>

          <!-- Ollama 版本更新提示：检测到新版时显示，点「更新」走原地替换（保留配置） -->
          <div v-if="selected.id === 'ollama' && ollamaUpdate?.hasUpdate" class="update-banner">
            <span class="ub-icon">↑</span>
            <div class="ub-text">
              <span class="ub-title">{{ t('ollamaUpdateAvailable', { from: ollamaUpdate.installed, to: ollamaUpdate.latest }) }}</span>
              <span class="ub-desc">{{ t('ollamaUpdateDesc') }}</span>
            </div>
            <button
              class="env-install-btn"
              :disabled="ui['ollama']?.installing || ollamaUpdateChecking"
              @click="updateOllama"
            >{{ ui['ollama']?.installing ? t('ollamaReplacing') : t('ollamaUpdateBtn') }}</button>
          </div>

          <!-- 端口冲突可视化提示：默认服务端口被其它程序占用时，启动会失败，提前给出明确警告 -->
          <div
            v-if="selected.hasService && selectedConflict && selectedConflict.occupied && !selectedConflict.ours"
            class="port-conflict-banner"
          >
            <span class="pc-icon">⚠</span>
            <span>{{ t('portConflict', { port: selectedConflict.port, pid: selectedConflict.pid }) }}</span>
          </div>

          <div v-if="selected.installed.length" class="ver-table">
            <div class="ver-row ver-head">
              <span class="col-ver">{{ t('version') }}</span>
              <span class="col-path">{{ t('installPath') }}</span>
              <span class="col-note">{{ t('envNote') }}</span>
              <span class="col-env">{{ t('envVar') }}</span>
              <span class="col-svc" v-if="selected.hasService">{{ t('svcStatus') }}</span>
              <span class="col-ops">{{ t('operations') }}</span>
            </div>
            <div
              v-for="ins in selected.installed"
              :key="ins.version"
              class="ver-row"
              :class="[ins.scope, { active: ins.active }]"
            >
              <div class="col-ver">
                <div class="ver-name">
                  <span v-if="ins.alias" class="ver-alias">{{ ins.alias }}</span>
                  <span class="ver-ver">{{ ins.version }}</span>
                </div>
                <span class="ver-scope" :class="ins.scope">
                  {{ ins.scope === 'system' ? t('scopeSystem') : t('scopePortable') }}
                </span>
              </div>
              <div class="col-path clickable" :title="t('openInExplorer') + ': ' + ins.path" @click="reveal(ins.path)">{{ ins.path }}</div>
              <div class="col-note" :title="ins.note">{{ ins.note || '—' }}</div>
              <div class="col-env">
                <span v-if="ins.inSystemPath" class="env-badge on" :title="t('envVarSetTitle')">{{ t('envVarSet') }}</span>
                <span v-else class="env-badge off" :title="t('envVarUnsetTitle')">{{ t('envVarUnset') }}</span>
              </div>
              <div class="col-svc" v-if="selected.hasService && (ins.scope !== 'linked' || selected.id === 'php')">
                <span class="status" :class="{ on: svcOn(selected, ins.version) }">
                  <span class="status-dot"></span>
                  {{ svcOn(selected, ins.version) ? t('svcRunning') : t('svcStopped') }}
                </span>
                <template v-if="svcOn(selected, ins.version)">
                  <button
                    class="svc-btn restart"
                    :disabled="restarting[selected.id + ins.version]"
                    @click="restartService(selected, ins)"
                  >{{ restarting[selected.id + ins.version] ? t('svcRestarting') : t('svcRestart') }}</button>
                  <button
                    class="svc-btn stop"
                    :disabled="stopping[selected.id + ins.version]"
                    @click="stopService(selected, ins)"
                  >{{ stopping[selected.id + ins.version] ? t('svcStopping') : t('svcStop') }}</button>
                  <button
                    v-if="consolePort(selected, ins) > 0"
                    class="svc-btn console"
                    @click="openConsole(consolePort(selected, ins))"
                  >{{ t('openConsole') }}</button>
                </template>
                <span v-if="svcPorts(selected, ins.version).length" class="svc-port">
                  {{ t('svcPort') }}:
                  <template v-if="selected.id === 'rabbitmq' && rabbitMgmt[ins.version]">5672 / 15672</template>
                  <template v-else>{{ svcPorts(selected, ins.version).join(' / ') }}</template>
                </span>
                <span
                  v-if="svcUsage(selected, ins.version)"
                  class="svc-usage"
                  :title="svcUsageTitle(selected, ins.version)"
                >{{ svcUsage(selected, ins.version) }}</span>
              </div>
              <div class="col-ops">
                <button class="op-btn menu-trigger" @click.stop="toggleMenu(ins.version)">
                  {{ t('operations') }}<span class="caret">▾</span>
                </button>
                <div v-if="openMenu === ins.version" class="op-menu">
                  <button class="op-item" :class="{ on: ins.inSystemPath }" @click="toggleEnvVar(selected, ins); openMenu = null">
                    {{ ins.inSystemPath ? t('unsetEnvVar') : t('setEnvVar') }}
                  </button>
                  <button class="op-item" @click="openAlias(selected, ins); openMenu = null">{{ t('setAlias') }}</button>
                  <template v-if="selected.id === 'php' && ins.scope !== 'system'">
                    <div class="op-sep"></div>
                    <button class="op-item" @click="openPHPConfig(selected, ins, 'ini'); openMenu = null">{{ t('phpIni') }}</button>
                    <button class="op-item" @click="openPHPConfig(selected, ins, 'disable'); openMenu = null">{{ t('phpDisableFunctions') }}</button>
                    <button class="op-item" @click="openPHPConfig(selected, ins, 'errorlog'); openMenu = null">{{ t('phpErrorLog') }}</button>
                    <button class="op-item" @click="openPHPConfig(selected, ins, 'ext'); openMenu = null">{{ t('phpExtensions') }}</button>
                  </template>
                  <template v-if="selected.id === 'redis' && ins.scope !== 'system'">
                    <div class="op-sep"></div>
                    <button class="op-item" @click="openRedisConfig(selected, ins, 'config'); openMenu = null">{{ t('redisConfig') }}</button>
                  </template>
                  <template v-if="selected.id === 'ftp' && ins.scope !== 'system'">
                    <div class="op-sep"></div>
                    <button class="op-item" @click="openFTPConfig(selected, ins); openMenu = null">{{ t('ftpConfig') }}</button>
                  </template>
                  <template v-if="configSupported && ins.scope !== 'system'">
                    <div class="op-sep"></div>
                    <button class="op-item" @click="openConfig(selected, ins); openMenu = null">{{ t('editConfig') }}</button>
                  </template>
                  <template v-if="selected.hasLog && ins.scope !== 'system'">
                    <div class="op-sep"></div>
                    <button class="op-item" @click="openLog(selected, ins); openMenu = null">{{ t('viewLog') }}</button>
                  </template>
                  <template v-if="selected.id === 'rabbitmq' && ins.scope !== 'system'">
                    <div class="op-sep"></div>
                    <button class="op-item" :disabled="mgmtEnabling" @click="toggleRabbitMgmt(ins); openMenu = null">
                      {{ mgmtEnabling ? '…' : (rabbitMgmt[ins.version] ? t('rabbitmqDisableMgmt') : t('rabbitmqEnableMgmt')) }}
                    </button>
                  </template>
                  <div class="op-sep"></div>
                  <button class="op-item danger" :disabled="ins.scope === 'system'" @click="askDelete(selected, ins)">
                    {{ t('deleteVersion') }}
                  </button>
                </div>
              </div>
            </div>
          </div>

          <div v-if="loadedOnce && !selected.installed.length" class="empty-state">
            <div class="empty-icon">∅</div>
            <div class="empty-text">{{ t('noInstalledVersion') }}</div>
            <div class="empty-hint">{{ t('installHint') }}</div>
          </div>
        </section>

        <!-- MCP 接入（MCP 专属）：监听地址、客户端配置、已开放工具 -->
        <section v-if="selected.id === 'mcp'" class="detail-block mcp-panel">
          <div class="block-head">
            <span class="block-title">{{ t('mcpPanelTitle') }}</span>
            <span class="block-count">{{ mcpInfo.running ? t('svcRunning') : t('svcNotStarted') }}</span>
            <button class="link-btn import-btn" :disabled="mcpLoading" @click="loadMCP">{{ t('refresh') }}</button>
          </div>

          <div v-if="mcpInfo.running" class="mcp-url-row">
            <code class="mcp-url">{{ mcpInfo.endpoint }}</code>
            <button class="op-btn small" @click="copyMCP(mcpInfo.endpoint)">{{ t('copyAddr') }}</button>
          </div>
          <div v-else class="env-msg">
            {{ t('mcpNotRunning') }}
          </div>

          <div class="mcp-level-row">
            <span class="mcp-label">{{ t('mcpToolLevel') }}</span>
            <select v-model.number="mcpInfo.maxLevel" class="env-input mcp-select" @change="setMCPLevel">
              <option :value="0">{{ t('mcpLevelReadOnly') }}</option>
              <option :value="1">{{ t('mcpLevelLowWrite') }}</option>
            </select>
            <span class="mcp-hint">{{ t('mcpHighRiskClosed') }}</span>
          </div>

          <template v-if="mcpInfo.running">
            <div class="mcp-cfg-head">
              <span>{{ t('mcpClaudeCodeCmd') }}</span>
              <button class="op-btn small" @click="copyMCP(mcpCfg.cli)">{{ t('copy') }}</button>
            </div>
            <pre class="mcp-code">{{ mcpCfg.cli }}</pre>

            <div class="mcp-cfg-head">
              <span>{{ t('mcpClientJson') }}</span>
              <button class="op-btn small" @click="copyMCP(mcpCfg.json)">{{ t('copy') }}</button>
            </div>
            <pre class="mcp-code">{{ mcpCfg.json }}</pre>
          </template>

          <div class="mcp-cfg-head">
            <span>{{ t('mcpExposedTools') }} {{ mcpTools.length }}</span>
          </div>
          <div class="mcp-tools">
            <div v-for="tool in mcpTools" :key="tool.name" class="mcp-tool-row">
              <span class="mcp-tool-name">{{ tool.name }}</span>
              <span class="badge" :class="tool.level > 0 ? 'warn' : 'plat'">{{ tool.level > 0 ? t('mcpToolWritable') : t('mcpToolReadOnly') }}</span>
              <span class="mcp-tool-desc">{{ tool.description }}</span>
            </div>
            <div v-if="!mcpTools.length" class="mcp-hint">{{ t('mcpNoTools') }}</div>
          </div>
        </section>

        <!-- WebDAV 共享（WebDAV 专属）：连接地址、账号、共享目录与各平台挂载命令。
             布局沿用 mcp-* 那几个纯布局类（url-row / cfg-head / code），不新增 CSS。 -->
        <section v-if="selected.id === 'webdav'" class="detail-block mcp-panel">
          <div class="block-head">
            <span class="block-title">{{ t('webdavPanelTitle') }}</span>
            <span class="block-count">{{ svcOn(selected, 'builtin') ? t('svcRunning') : t('svcNotStarted') }}</span>
            <button class="link-btn import-btn" @click="loadWebDAV">{{ t('refresh') }}</button>
          </div>

          <div class="mcp-url-row">
            <code class="mcp-url">{{ webdavURL }}</code>
            <button class="op-btn small" @click="copyWebDAV(webdavURL)">{{ t('copyAddr') }}</button>
            <button class="op-btn small" :disabled="!svcOn(selected, 'builtin')" @click="openConsole(webdavInfo.port)">{{ t('webdavOpenBrowser') }}</button>
          </div>

          <div class="mcp-level-row">
            <span class="mcp-label">{{ t('webdavAccount') }}</span>
            <code class="mcp-url">{{ webdavInfo.username }} / {{ webdavInfo.password }}</code>
            <button class="op-btn small" @click="copyWebDAV(webdavInfo.username + ' / ' + webdavInfo.password)">{{ t('webdavCopyAccount') }}</button>
          </div>

          <div class="mcp-level-row">
            <span class="mcp-label">{{ t('webdavRoot') }}</span>
            <code class="mcp-url">{{ webdavInfo.root || '—' }}</code>
            <button class="op-btn small" @click="copyWebDAV(webdavInfo.root)">{{ t('webdavCopyPath') }}</button>
          </div>

          <div class="mcp-level-row">
            <span class="mcp-label">{{ t('webdavMode') }}</span>
            <span class="mcp-hint">{{ webdavInfo.readOnly ? t('webdavModeReadOnly') : t('webdavModeReadWrite') }}</span>
          </div>

          <div v-if="!svcOn(selected, 'builtin')" class="env-msg">
            {{ t('webdavNotRunning') }}
          </div>

          <template v-if="webdavExposed">
            <div class="mcp-cfg-head">
              <span>{{ t('webdavListenAll') }}</span>
            </div>
            <div class="env-msg error">
              {{ t('webdavExposedWarn') }}
            </div>
          </template>

          <div class="mcp-cfg-head">
            <span>{{ t('webdavClientAccess') }}</span>
          </div>
          <template v-for="c in webdavCmds" :key="c.label">
            <div class="mcp-cfg-head">
              <span>{{ c.label }}</span>
              <button class="op-btn small" @click="copyWebDAV(c.cmd)">{{ t('copy') }}</button>
            </div>
            <pre class="mcp-code">{{ c.cmd }}</pre>
          </template>

          <div class="mcp-cfg-head">
            <span>{{ t('webdavConfigFile') }}</span>
            <button class="op-btn small" @click="copyWebDAV(webdavInfo.path)">{{ t('copy') }}</button>
          </div>
          <pre class="mcp-code">{{ webdavInfo.path || '—' }}</pre>
        </section>

        <!-- 安装新版本（Git 不展示：Git 为单版本，检测不到时由上方空状态提供一键安装；
             MCP / WebDAV 为内置服务，无版本可装，后端 Install 直接返回错误，故一并隐藏） -->
        <section v-if="selected.id !== 'git' && selected.id !== 'mcp' && selected.id !== 'webdav' && s" class="detail-block install-card">
          <div class="block-head">
            <span class="block-title">{{ t('installNewVersion') }}</span>
          </div>
          <div class="install-grid">
            <!-- 版本号输入 + 可选列表 -->
            <div class="install-input-wrap">
              <input
                v-model="versionInput"
                class="env-input version-input"
                :placeholder="s.available.length ? t('selectVersion') : t('availableVersions')"
                :disabled="s.installing"
                @focus="s.listExpanded = true; s.fetching || s.available.length || loadAvailable(selected.id)"

              />
              <datalist :id="'dl-' + selected.id">
                <option v-for="v in s.available" :key="v" :value="v" />
              </datalist>
              <!-- 展开/收起列表按钮 -->
              <button
                class="version-toggle-btn"
                :disabled="s.installing"
                @click="s.listExpanded = !s.listExpanded; s.fetching || s.available.length || loadAvailable(selected.id)"
                :title="t('selectVersion')"
              >{{ s.fetching ? '…' : (s.listExpanded ? '▴' : '▾') }}</button>
              <!-- 展开的版本列表 -->
              <div v-if="s.listExpanded" class="version-list-panel">
                <div v-if="s.fetching" class="version-list-loading">{{ t('loading') }}…</div>
                <div v-else-if="s.loadError" class="version-list-error"
                  @click="loadAvailable(selected.id)">{{ t('fetchFailed') }}: {{ s.loadError }}
                  <span class="retry-link">{{ t('retry') }}</span></div>
                <div v-else-if="!s.available.length" class="version-list-empty"
                  @click="loadAvailable(selected.id)">{{ t('fetchVersions') }}</div>
                <template v-else>
                  <div
                    v-for="v in s.available"
                    :key="v"
                    class="version-item"
                    :class="{ active: v === s.version }"
                    @click="s.version = v; s.listExpanded = false"
                  >{{ v }}</div>
                  <div v-if="selected.id === 'node' && s.available.length >= 60" class="version-list-note">
                    {{ t('versionListTruncated') }}
                  </div>
                </template>
              </div>
            </div>
            <!-- 手动拉取按钮（始终可见，方便换源后重新拉取） -->
            <button
              class="link-btn"
              :disabled="s.fetching || s.installing"
              @click="loadAvailable(selected.id)"
              :title="s.loadError ? t('retry') : t('refreshList')"
            >{{ s.fetching ? t('loading') : (s.loadError ? t('retry') : t('refreshList')) }}</button>
            <select
              v-model="stateFor(selected.id, selected).source"
              class="env-select"
              :disabled="stateFor(selected.id, selected).installing"
            >
              <option v-for="s in selected.sources" :key="s.id" :value="s.id">{{ s.name }}</option>
            </select>
            <button
              class="env-install-btn"
              :class="{ busy: stateFor(selected.id, selected).installing }"
              :disabled="stateFor(selected.id, selected).installing || !s.version"
              :title="!s.version ? t('versionRequired') : ''"
              @click="install(selected)"
            >{{ stateFor(selected.id, selected).installing ? t('installing') : t('install') }}</button>
          </div>

          <!-- 上游有更高版本时提示可更新（点击即填入版本号并触发安装） -->
          <div v-if="newestUpdate" class="env-update-hint">
            <span class="env-update-dot"></span>
            <span>{{ t('envNewVersion') }}: {{ newestUpdate.from }} → {{ newestUpdate.to }}</span>
            <button class="link-btn" :disabled="stateFor(selected.id, selected).installing" @click="applyUpdate(newestUpdate.to)">
              {{ t('envUpdateTo') }}
            </button>
          </div>

          <input
            v-if="stateFor(selected.id, selected).source === 'custom'"
            v-model="stateFor(selected.id, selected).custom"
            class="env-input custom"
            :placeholder="t('customSourcePlaceholder')"
            :disabled="stateFor(selected.id, selected).installing"
          />

          <div v-if="stateFor(selected.id, selected).installing" class="env-progress">
            <div class="env-progress-bar">
              <div
                class="env-progress-fill"
                :class="{ indeterminate: percent(stateFor(selected.id, selected)) < 0 }"
                :style="{ width: (percent(stateFor(selected.id, selected)) >= 0 ? percent(stateFor(selected.id, selected)) + '%' : '40%') }"
              ></div>
            </div>
            <div class="env-progress-text">
              <span>{{ stateFor(selected.id, selected).stage }}</span>
              <span v-if="percent(stateFor(selected.id, selected)) >= 0">{{ percent(stateFor(selected.id, selected)) }}%</span>
              <span v-else-if="stateFor(selected.id, selected).written > 0">{{ (stateFor(selected.id, selected).written / 1048576).toFixed(1) }} MB</span>
              <span v-if="percent(stateFor(selected.id, selected)) >= 0 && stateFor(selected.id, selected).speed > 0">{{ formatSpeed(stateFor(selected.id, selected).speed) }} · {{ formatEta(stateFor(selected.id, selected).eta) }}</span>
            </div>
          </div>
          <p v-else-if="stateFor(selected.id, selected).message" class="env-msg" :class="{ error: stateFor(selected.id, selected).error }">{{ stateFor(selected.id, selected).message }}</p>
        </section>
        </template>

        <div v-else class="empty-state">
          <div class="empty-icon">∅</div>
          <div class="empty-text">{{ t('noInstalledVersion') }}</div>
        </div>
      </main>
    </div>

